const char *thermo_token_data(int encoding) { return encoding == 0 ? table_0 : encoding == 1 ? table_1 : 0; }
size_t thermo_token_uncompressed_size(int encoding) { return encoding == 0 ? 1245374 : encoding == 1 ? 2597666 : 0; }
int thermo_token_inflate(const uint8_t *src, size_t count, uint8_t *out, size_t *length) { uLongf size = *length; int result = uncompress(out, &size, src, count); *length = size; return result; }
